"65\" y=\"136\" font-size=\"10.5\" fill=\"#7f1d1d\" text-anchor=\"middle\">تغذية غير ذاتية (تبتلع)</text>\n  </g>\n\n  <!-- Kingdom 2: Plantae -->\n  <g transform=\"translate(180, 80)\" filter=\"url(#shadowBio)\">\n    <rect width=\"130\" height=\"150\" rx=\"10\" fill=\"#dcfce7\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n    <text x=\"65\" y=\"30\" font-size=\"24\" text-anchor=\"middle\">🌿</text>\n    <text x=\"65\" y=\"55\" font-size=\"14\" font-weight=\"bold\" fill=\"#166534\" text-anchor=\"middle\">مملكة النبات</text>\n    <text x=\"65\" y=\"73\" font-size=\"11\" fill=\"#15803d\" text-anchor=\"middle\">Plantae</text>\n    <line x1=\"15\" y1=\"82\" x2=\"115\" y2=\"82\" stroke=\"#86efac\" stroke-width=\"1\"/>\n    <text x=\"65\" y=\"100\" font-size=\"10.5\" fill=\"#14532d\" text-anchor=\"middle\">عديدة الخلايا</text>\n    <text x=\"65\" y=\"118\" font-size=\"10.5\" fill=\"#14532d\" text-anchor=\"middle\">بلاستيدات وبناء ضوئي</text>\n    <text x=\"65\" y=\"136\" font-size=\"10.5\" fill=\"#14532d\" text-anchor=\"middle\">تغذية ذاتية (منتجة)</text>\n  </g>\n\n  <!-- Kingdom 3: Fungi -->\n  <g transform=\"translate(330, 80)\" filter=\"url(#shadowBio)\">\n    <rect width=\"130\" height=\"150\" rx=\"10\" fill=\"#ffedd5\" stroke=\"#f97316\" stroke-width=\"2\"/>\n    <text x=\"65\" y=\"30\" font-size=\"24\" text-anchor=\"middle\">🍄</text>\n    <text x=\"65\" y=\"55\" font-size=\"14\" font-weight=\"bold\" fill=\"#9a3412\" text-anchor=\"middle\">مملكة الفطريات</text>\n    <text x=\"65\" y=\"73\" font-size=\"11\" fill=\"#c2410c\" text-anchor=\"middle\">Fungi</text>\n    <line x1=\"15\" y1=\"82\" x2=\"115\" y2=\"82\" stroke=\"#fed7aa\" stroke-width=\"1\"/>\n    <text x=\"65\" y=\"100\" font-size=\"10.5\" fill=\"#7c2d12\" text-anchor=\"middle\">حقيقية النواة</text>\n    <text x=\"65\" y=\"118\" font-size=\"10.5\" fill=\"#7c2d12\" text-anchor=\"middle\">خالية من الكلوروفيل</text>\n    <text x=\"65\" y=\"136\" font-size=\"10.5\" fill=\"#7c2d12\" text-anchor=\"middle\">تغذية رمية أو متطفلة</text>\n  </g>\n\n  <!-- Kingdom 4: Protista -->\n  <g transform=\"translate(480, 80)\" filter=\"url(#shadowBio)\">\n    <rect width=\"130\" height=\"150\" rx=\"10\" fill=\"#e0e7ff\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n    <text x=\"65\" y=\"30\" font-size=\"24\" text-anchor=\"middle\">🔬</text>\n    <text x=\"65\" y=\"55\" font-size=\"14\" font-weight=\"bold\" fill=\"#3730a3\" text-anchor=\"middle\">مملكة الطليعيات</text>\n    <text x=\"65\" y=\"73\" font-size=\"11\" fill=\"#4f46e5\" text-anchor=\"middle\">Protista</text>\n    <line x1=\"15\" y1=\"82\" x2=\"115\" y2=\"82\" stroke=\"#c7d2fe\" stroke-width=\"1\"/>\n    <text x=\"65\" y=\"100\" font-size=\"10.5\" fill=\"#312e81\" text-anchor=\"middle\">حقيقية النواة</text>\n    <text x=\"65\" y=\"118\" font-size=\"10.5\" fill=\"#312e81\" text-anchor=\"middle\">وحيدة الخلية غالباً</text>\n    <text x=\"65\" y=\"136\" font-size=\"10.5\" fill=\"#312e81\" text-anchor=\"middle\">أميبا، براميسيوم، يوغلينا</text>\n  </g>\n\n  <!-- Kingdom 5: Monera -->\n  <g transform=\"translate(630, 80)\" filter=\"url(#shadowBio)\">\n    <rect width=\"120\" height=\"150\" rx=\"10\" fill=\"#fef08a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n    <text x=\"60\" y=\"30\" font-size=\"24\" text-anchor=\"middle\">🧫</text>\n    <text x=\"60\" y=\"55\" font-size=\"13\" font-weight=\"bold\" fill=\"#854d0e\" text-anchor=\"middle\">مملكة البدائيات</text>\n    <text x=\"60\" y=\"73\" font-size=\"11\" fill=\"#a16207\" text-anchor=\"middle\">Monera</text>\n    <line x1=\"15\" y1=\"82\" x2=\"105\" y2=\"82\" stroke=\"#fef08a\" stroke-width=\"1\"/>\n    <text x=\"60\" y=\"100\" font-size=\"10.5\" fill=\"#713f12\" text-anchor=\"middle\">بدائية النواة</text>\n    <text x=\"60\" y=\"118\" font-size=\"10.5\" fill=\"#713f12\" text-anchor=\"middle\">لا غشاء نووي يحيطها</text>\n    <text x=\"60\" y=\"136\" font-size=\"10.5\" fill=\"#713f12\" text-anchor=\"middle\">البكتيريا بأنواعها</text>\n  </g>\n\n  <!-- Branching Lines -->\n  <path d=\"M 95 230 L 95 270 Q 95 290 245 290 L 390 290\" stroke=\"#059669\" stroke-width=\"3\" fill=\"none\"/>\n  <path d=\"M 245 230 L 245 290\" stroke=\"#059669\" stroke-width=\"3\" fill=\"none\"/>\n  <path d=\"M 395 230 L 395 290\" stroke=\"#059669\" stroke-width=\"3\" fill=\"none\"/>\n  <path d=\"M 545 230 L 545 290 Q 545 310 440 310\" stroke=\"#059669\" stroke-width=\"3\" fill=\"none\"/>\n  <path d=\"M 690 230 L 690 350 L 390 350\" stroke=\"#d97706\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"6,4\"/>\n\n  <!-- Center Node: Eukaryotes -->\n  <g transform=\"translate(230, 295)\" filter=\"url(#shadowBio)\">\n    <rect width=\"320\" height=\"40\" rx=\"8\" fill=\"#059669\"/>\n    <text x=\"160\" y=\"25\" font-size=\"14\" font-weight=\"bold\" fill=\"#ffffff\" text-anchor=\"middle\">كائنات حقيقية النواة (Eukaryota) - غشاء نووي وعضيات</text>\n  </g>\n\n  <!-- Bottom Node: Root of Life -->\n  <g transform=\"translate(190, 360)\" filter=\"url(#shadowBio)\">\n    <rect width=\"400\" height=\"50\" rx=\"10\" fill=\"#1e293b\"/>\n    <text x=\"200\" y=\"24\" font-size=\"13\" font-weight=\"bold\" fill=\"#f8fafc\" text-anchor=\"middle\">أصل الحياة والخلية الأولى (Tree of Life Origin)</text>\n    <text x=\"200\" y=\"42\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"middle\">التمايز الأساسي: التركيب الخلوي وعدد الخلايا ونمط التغذية والحركة</text>\n  </g>\n</svg>"
