  "svg": "<svg viewBox=\"0 0 740 480\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\" style=\"font-family: 'Segoe UI', Tahoma, sans-serif;\">\n  <defs>\n    <linearGradient id=\"skyGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0f172a\" />\n      <stop offset=\"30%\" stop-color=\"#1e293b\" />\n      <stop offset=\"70%\" stop-color=\"#fde047\" stop-opacity=\"0.3\" />\n      <stop offset=\"100%\" stop-color=\"#f8fafc\" />\n    </linearGradient>\n    <linearGradient id=\"ozoneGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.6\" />\n      <stop offset=\"45%\" stop-color=\"#ef4444\" stop-opacity=\"0.8\" />\n      <stop offset=\"55%\" stop-color=\"#ef4444\" stop-opacity=\"0.8\" />\n      <stop offset=\"100%\" stop-color=\"#38bdf8\" stop-opacity=\"0.6\" />\n    </linearGradient>\n  </defs>\n  <rect width=\"740\" height=\"480\" rx=\"14\" fill=\"url(#skyGrad)\" />\n  \n  <!-- Stratosphere & Ozone Layer -->\n  <rect x=\"30\" y=\"35\" width=\"680\" height=\"28\" rx=\"14\" fill=\"url(#ozoneGrad)\" />\n  <text x=\"370\" y=\"54\" font-size=\"12\" font-weight=\"bold\" fill=\"#ffffff\" text-anchor=\"middle\">طبقة الأوزون (O₃) في الستراتوسفير — [ثقب وتآكل بفعل CFCs]</text>\n  \n  <!-- Sun & UV rays -->\n  <circle cx=\"80\" cy=\"95\" r=\"26\" fill=\"#fbbf24\" filter=\"drop-shadow(0 0 8px #f59e0b)\" />\n  <text x=\"80\" y=\"100\" font-size=\"11\" font-weight=\"bold\" fill=\"#78350f\" text-anchor=\"middle\">الشمس</text>\n  \n  <!-- Solar Radiation -->\n  <path d=\"M110,105 L220,180\" stroke=\"#f59e0b\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\" />\n  <text x=\"165\" y=\"135\" font-size=\"10\" font-weight=\"bold\" fill=\"#d97706\">إشعاع شمسي نافذ</text>\n  \n  <!-- Greenhouse Gas Blanket -->\n  <path d=\"M40,160 Q200,140 370,160 T700,160\" fill=\"none\" stroke=\"#fb923c\" stroke-width=\"8\" stroke-linecap=\"round\" opacity=\"0.75\" />\n  <rect x=\"260\" y=\"146\" width=\"220\" height=\"24\" rx=\"6\" fill=\"#fff7ed\" stroke=\"#ea580c\" stroke-width=\"1.5\" />\n  <text x=\"370\" y=\"163\" font-size=\"11\" font-weight=\"bold\" fill=\"#c2410c\" text-anchor=\"middle\">طبقة الغازات الدفيئة (CO₂ + CH₄)</text>\n  \n  <!-- Trapped Heat Arrow -->\n  <path d=\"M280,240 Q250,180 220,240\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"3\" marker-end=\"url(#arrow)\" />\n  <text x=\"250\" y=\"210\" font-size=\"10\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">احتباس حراري ♨️</text>\n\n  <!-- Factory & Emissions -->\n  <g transform=\"translate(480, 260)\">\n    <rect x=\"0\" y=\"70\" width=\"120\" height=\"80\" fill=\"#475569\" rx=\"4\" />\n    <rect x=\"20\" y=\"0\" width=\"24\" height=\"70\" fill=\"#334155\" />\n    <rect x=\"70\" y=\"20\" width=\"20\" height=\"50\" fill=\"#334155\" />\n    <!-- Smoke clouds -->\n    <ellipse cx=\"32\" cy=\"-15\" rx=\"28\" ry=\"16\" fill=\"#64748b\" opacity=\"0.8\" />\n    <ellipse cx=\"80\" cy=\"5\" rx=\"22\" ry=\"14\" fill=\"#64748b\" opacity=\"0.7\" />\n    <text x=\"60\" y=\"110\" font-size=\"11\" font-weight=\"bold\" fill=\"#f8fafc\" text-anchor=\"middle\">مصانع ومحطات</text>\n    <text x=\"32\" y=\"-12\" font-size=\"9\" font-weight=\"bold\" fill=\"#f1f5f9\" text-anchor=\"middle\">SO₂ / NOₓ</text>\n    <text x=\"80\" y=\"8\" font-size=\"9\" font-weight=\"bold\" fill=\"#f1f5f9\" text-anchor=\"middle\">CO₂</text>\n  </g>\n\n  <!-- Acid Clouds and Rain -->\n  <g transform=\"translate(320, 200)\">\n    <path d=\"M20,30 Q35,10 60,20 Q80,5 110,20 Q130,10 145,30 Q160,50 135,65 Q110,75 75,70 Q40,75 20,60 Q5,45 20,30 Z\" fill=\"#94a3b8\" stroke=\"#64748b\" stroke-width=\"1.5\" />\n    <text x=\"82\" y=\"46\" font-size=\"10\" font-weight=\"bold\" fill=\"#1e293b\" text-anchor=\"middle\">سحابة حامضية</text>\n    <!-- Rain droplets -->\n    <line x1=\"45\" y1=\"80\" x2=\"35\" y2=\"115\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-dasharray=\"5,4\" />\n    <line x1=\"75\" y1=\"80\" x2=\"65\" y2=\"120\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-dasharray=\"5,4\" />\n    <line x1=\"105\" y1=\"80\" x2=\"95\" y2=\"115\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-dasharray=\"5,4\" />\n    <line x1=\"130\" y1=\"80\" x2=\"120\" y2=\"120\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-dasharray=\"5,4\" />\n    <text x=\"85\" y=\"136\" font-size=\"11\" font-weight=\"bold\" fill=\"#b91c1c\" text-anchor=\"middle\">أمطار حامضية (H₂SO₄ + HNO₃)</text>\n  </g>\n\n  <!-- Ground & Damaged Environment -->\n  <path d=\"M0,410 Q200,395 450,415 T740,410 L740,480 L0,480 Z\" fill=\"#713f12\" />\n  <rect x=\"0\" y=\"430\" width=\"740\" height=\"50\" fill=\"#451a03\" />\n\n  <!-- Damaged Trees (Left) -->\n  <g transform=\"translate(120, 310)\">\n    <path d=\"M20,100 L20,30 L10,15 M20,45 L35,25 M20,60 L5,45\" stroke=\"#78350f\" stroke-width=\"4\" stroke-linecap=\"round\" fill=\"none\" />\n    <text x=\"20\" y=\"118\" font-size=\"10\" font-weight=\"bold\" fill=\"#fef08a\" text-anchor=\"middle\">غابات متضررة وميتة</text>\n  </g>\n\n  <!-- Polluted Lake (Middle) -->\n  <g transform=\"translate(220, 410)\">\n    <ellipse cx=\"90\" cy=\"20\" rx=\"80\" ry=\"18\" fill=\"#047857\" opacity=\"0.85\" />\n    <text x=\"90\" y=\"24\" font-size=\"10\" font-weight=\"bold\" fill=\"#ffffff\" text-anchor=\"middle\">مياه ملوثة وحمضية تقتل الأسماك</text>\n  </g>\n\n  <!-- Bottom Explanatory Banner -->\n  <g transform=\"translate(40, 440)\">\n    <rect x=\"0\" y=\"0\" width=\"660\" height=\"30\" rx=\"6\" fill=\"#1e293b\" opacity=\"0.9\" />\n    <text x=\"330\" y=\"20\" font-size=\"11\" font-weight=\"bold\" fill=\"#f8fafc\" text-anchor=\"middle\">💡 الحل: خفض انبعاثات الكربون، الطاقة المتجددة، فلاتر المصانع، واستبدال مركبات الفريون لحماية الأوزون.</text>\n  </g>\n</svg>"
