window.getBiologyDiagram = function(lessonId) {
  if (!window.BIOLOGY_DIAGRAMS) return null;
  return window.BIOLOGY_DIAGRAMS.find(function(d) { return d.lessonId === Number(lessonId); }) || null;
};

window.getBiologyDiagramsForLesson = function(lessonId) {
  if (!window.BIOLOGY_DIAGRAMS) return [];
  return window.BIOLOGY_DIAGRAMS.filter(function(d) { return d.lessonId === Number(lessonId); });
};
